#!/usr/bin/env python3
"""Regenerate the fetch-plan-v1 vectors.

Every value here is written by hand; this script only lays the files out and
computes the canonical bytes and digests, so a reviewer can change one value
and rerun it. Run from anywhere:

    python3 test-vectors/fetch-plan-v1/generate.py

Add --check to compare every generated file without writing it.

Canonical bytes are RFC 8785 (JCS). The vectors hold only objects, arrays,
null, ASCII strings, booleans and small integers, and for that domain JCS is exactly
`json.dumps(sort_keys=True, separators=(",", ":"), ensure_ascii=False)`: keys
sort by code point, which equals UTF-16 order for ASCII. The script refuses
floats and non-ASCII strings rather than emit bytes another JCS
implementation might write differently. The Rust test
(`crates/prefrontal-core/tests/it/fetch_plan_v1_vectors.rs`) recomputes every
file with an independent RFC 8785 implementation.
"""

from __future__ import annotations

import argparse
import copy
import hashlib
import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument("--check", action="store_true", help="verify generated bytes without writing files")
CHECK = parser.parse_args().check
checked_files = 0
drifted_files = []


# --------------------------------------------------------------------------
# canonical bytes
# --------------------------------------------------------------------------


def check_domain(value, where="$"):
    if isinstance(value, bool) or value is None:
        return
    if isinstance(value, float):
        raise ValueError(f"{where}: floats are outside the vector domain")
    if isinstance(value, int):
        if abs(value) > 2**53 - 1:
            raise ValueError(f"{where}: integer outside the exact f64 range")
        return
    if isinstance(value, str):
        if not value.isascii():
            raise ValueError(f"{where}: non-ASCII string")
        return
    if isinstance(value, list):
        for index, item in enumerate(value):
            check_domain(item, f"{where}[{index}]")
        return
    if isinstance(value, dict):
        for key, item in value.items():
            if not key.isascii():
                raise ValueError(f"{where}: non-ASCII key {key!r}")
            check_domain(item, f"{where}.{key}")
        return
    raise ValueError(f"{where}: unsupported type {type(value).__name__}")


def jcs(value) -> bytes:
    check_domain(value)
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def pretty(value) -> str:
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def write_text(path: Path, text: str):
    write_bytes(path, text.encode("utf-8"))


def write_bytes(path: Path, data: bytes):
    global checked_files
    checked_files += 1
    if CHECK:
        if not path.is_file() or path.read_bytes() != data:
            drifted_files.append(str(path.relative_to(HERE)))
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(data)


def write_triple(folder: str, name: str, value) -> str:
    """Write <name>.json (pretty), <name>.jcs (exact bytes, no newline) and
    <name>.sha256 (64 lowercase hex, no newline). Returns the digest."""
    canonical = jcs(value)
    digest = sha256_hex(canonical)
    write_text(HERE / folder / f"{name}.json", pretty(value))
    write_bytes(HERE / folder / f"{name}.jcs", canonical)
    write_bytes(HERE / folder / f"{name}.sha256", digest.encode("ascii"))
    return digest


