# Magic Context's non-compacting head catalog, read from the sibling checkout:
# magic-context/docs/designs/mc-tool-catalog-v1/tools-only.answer.json:201-204
# and crates/mc-module/src/tool_catalog.rs:640-641. Workers and readers do not
# receive this catalog unless Magic Context is the plan's compaction provider.
MC_NON_COMPACTING_TOOLS = ["ctx_memory", "ctx_note", "ctx_search"]


def composition(entries: dict[str, list[str]]) -> dict:
    """The composition for {provider: [tool names]}. Providers sort by module
    id, tools by name and each tool's tags bytewise, so the bytes depend only
    on the session's final set, never on plan order."""
    providers = []
    for provider in sorted(entries):
        tools = []
        for name in sorted(entries[provider]):
            tools.append(
                {"name": name, "capabilities": sorted(TOOLS[provider][name])}
            )
        providers.append({"provider": provider, "tools": tools})
    return {"providers": providers}


def item(provider, preset, params=None, **extra):
    value = {"provider": provider, "preset": preset, "params": params or {}}
    value.update(extra)
    return value


