# Core copies each provider preset's transform.declare policy and budget
# into the plan subscription before hashing the session composition. These
# standalone hook fixtures explicitly use a runner that declares both hooks
# and compaction; Broca production plans declare neither.
DECLARED_PRE_TOOL = {
    "hook": "pre_tool", "phase": "validate", "ops": [],
    "on_unavailable": "pass", "budget_ms": 1000,
}
for name, policy, budget in [
    ("pre-tool-declared", "pass", 1000),
    ("pre-tool-tightened", "refuse", 500),
]:
    comp = composition({"magic-context": [], "prefrontal-core": []})
    compositions[name] = comp
    subscription = {**DECLARED_PRE_TOOL, "on_unavailable": policy, "budget_ms": budget}
    plans[name] = (name, plan(
        [], [item("prefrontal-core", "worker", {"role": "mason"})],
        item("magic-context", "worker"),
        [item("magic-context", "worker", subscriptions=[subscription])], comp,
    ))

two_phase = copy.deepcopy(plans["pre-tool-declared"][1])
two_phase["step_transform_items"][0]["subscriptions"].insert(
    0, {**DECLARED_PRE_TOOL, "phase": "mutate"})
compositions["pre-tool-two-phase"] = composition({"magic-context": [], "prefrontal-core": []})
plans["pre-tool-two-phase"] = ("pre-tool-two-phase", two_phase)

# Include on_unavailable and budget_ms in the composition hash, not only
# the plan identity. Core always serializes the step-transform list, as `[]`
# when the session has none, in the composition as in the plan.
for comp_name, value in plans.values():
    if "compaction_item" in value:
        compositions[comp_name]["compaction"] = {
            "provider": value["compaction_item"]["provider"]}
    else:
        compositions[comp_name].pop("compaction", None)
    compositions[comp_name]["step_transform_items"] = copy.deepcopy(value["step_transform_items"])
    value["composition"] = compositions[comp_name]
    value["composition_digest"] = sha256_hex(jcs(value["composition"]))

# --------------------------------------------------------------------------
# write compositions and plans
# --------------------------------------------------------------------------

for name, value in compositions.items():
    write_triple("compositions", name, value)

for name, (comp_name, value) in plans.items():
    assert value["composition"] == compositions[comp_name], name
    write_triple("plans", name, value)


def plan_ref(name: str) -> dict:
    return {"plan": f"plans/{name}.json", "composition": f"compositions/{plans[name][0]}.json"}


