def catalog_reply(provider, comp_digest, tools, text=False):
    """The parts of a provider's tool.catalog answer the staleness check
    reads: tool names stand in for the full tool entries."""
    reply = {
        "provider": provider,
        "answer": {"composition_digest": comp_digest, "tool_names": tools},
    }
    if text:
        reply["answer"]["system_text"] = {"composition_digest": comp_digest}
    return reply


