for name, value in outcomes.items():
    value.setdefault("settled", "BROCA, room #881")
    if "runner_declaration" not in value:
        plan_path = value.get("plan")
        plan_name = Path(plan_path).stem if isinstance(plan_path, str) else None
        inline_plan = value.get("plan_inline")
        has_hooks = plan_name in HOOK_PLAN_NAMES or (
            isinstance(inline_plan, dict)
            and bool(inline_plan.get("step_transform_items"))
        )
        has_compaction = (plan_name in HOOK_PLAN_NAMES) or (
            isinstance(inline_plan, dict)
            and "compaction_item" in inline_plan
        )
        value["runner_declaration"] = {
            "hooks": has_hooks,
            "compaction": has_compaction,
        }
    write_text(HERE / "admission" / f"{name}.json", pretty(value))

print(f"{'computed' if CHECK else 'wrote'} {len(compositions)} compositions, {len(plans)} plans, "
      f"{len(calls)} calls, {len(outcomes)} admission outcomes")

# Publish the complete current digest table with the vectors, so regeneration
# cannot leave the wire reference documenting old identities.
DIGEST_HEADING = "## Current digests (role presets and compaction)"
table = [DIGEST_HEADING, "",
         "Generated by `generate.py`. All Broca vectors omit compaction; every item",
         "uses a role preset. Earlier migration tables are historical, not current pins.", "",
         "| Plan vector | Plan identity SHA-256 | Composition SHA-256 |",
         "|---|---|---|"]
for name, (_, value) in plans.items():
    identity = sha256_hex(jcs(value))
    digest = value["composition_digest"]
    table.append(f"| `{name}` | `{identity}` | `{digest}` |")
    print(f"{name}: plan={identity} composition={digest}")
readme = HERE / "README.md"
prefix = readme.read_text(encoding="utf-8").split(DIGEST_HEADING)[0].rstrip()
write_text(readme, prefix + "\n\n" + "\n".join(table) + "\n")
if CHECK:
    print(f"fetch-plan-v1: {checked_files} files checked, {len(drifted_files)} drifted")
    if drifted_files:
        print("\n".join(drifted_files))
        sys.exit(1)
